const source = $input.first().json;
const value = String(source.ioc_value || source.value || source.src_ip || '').trim();
const ipv4 = /^(?:(?:25[0-5]|2[0-4]\d|1?\d?\d)\.){3}(?:25[0-5]|2[0-4]\d|1?\d?\d)$/;
const valid = ipv4.test(value);
const escaped = value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
return [{ json: {
  observable: { type: 'ip', value: valid ? value : null },
  valid_input: valid,
  validation_error: valid ? '' : 'Expected a valid IPv4 observable.',
  splunk_query: valid ? `index=wazuh (data.win.eventdata.ipAddress="${escaped}" OR data.srcip="${escaped}" OR srcip="${escaped}") earliest=-24h latest=now | head 20` : ''
} }];

return [{ json: {
  observable: $input.first().json.observable,
  enrichment: {
    status: 'invalid_input',
    message: $input.first().json.validation_error,
    splunk_status: 'skipped',
    misp_status: 'skipped',
    enrichment_degraded: false
  }
} }];

const input = $('Validate IPv4 Observable').item.json;
const splunk = $('Splunk IP Context').item.json || {};
const misp = $input.item.json || {};
const errorText = (value) => String(value?.message || value || '').slice(0, 400);
const splunkStatus = splunk.error ? 'error' : 'ok';
const mispStatus = misp.error ? 'error' : 'ok';
const rows = Array.isArray(splunk.rows) ? splunk.rows : [];
const results = Array.isArray(splunk.result) ? splunk.result : (splunk.result ? [splunk.result] : rows);
const attrs = misp?.response?.Attribute || misp?.Attribute || [];
const matches = Array.isArray(attrs) ? attrs.slice(0, 5).map(a => ({
  type: a.type || null,
  value: a.value || null,
  category: a.category || null,
  event: a.Event?.info || null,
  threat_level: a.Event?.threat_level_id || null
})) : [];
const rawMatches = Array.isArray(attrs) ? attrs.slice(0, 5) : [];
const isInternalControlledObservation = (a) => {
  const eventInfo = String(a?.Event?.info || '');
  const toIds = String(a?.to_ids ?? '').toLowerCase();
  return /^SOC Lab - Controlled Internal Observation -/.test(eventInfo) &&
    (toIds === '' || toIds === '0' || toIds === 'false');
};
const internalObservationMatches = rawMatches.filter(isInternalControlledObservation);
const externalIocMatches = rawMatches.filter(a => !isInternalControlledObservation(a));
return [{ json: {
  observable: input.observable,
  enrichment: {
    status: splunkStatus === 'error' || mispStatus === 'error' ? 'degraded' : 'ok',
    splunk_status: splunkStatus,
    splunk_error: splunkStatus === 'error' ? errorText(splunk.error) : '',
    splunk_events_found: results.length,
    splunk_summary: results.slice(0, 10),
    misp_status: mispStatus,
    misp_error: mispStatus === 'error' ? errorText(misp.error) : '',
    misp_hits_found: matches.length,
    misp_matches: matches,
    misp_internal_observation_matches: internalObservationMatches.length,
    misp_has_internal_observation: internalObservationMatches.length > 0,
    misp_external_ioc_matches: externalIocMatches.length,
    misp_is_known_ioc: externalIocMatches.length > 0,
    enrichment_degraded: splunkStatus === 'error' || mispStatus === 'error'
  }
} }];
